ruleSearch.author:
class.book-card__meta@text@js:{
  let m = result.match(/作者：(.+?)[分类]/);
  return m ? m[1].trim() : ''
}

ruleSearch.kind:
class.book-card__meta@text@js:{
  let m = result.match(/分类：(.+?)$/);
  return m ? m[1].replace(/[连载中|完结|已完结]/,'').trim() : ''
}

ruleSearch.bookUrl:
@js:{
  let onclick = java.toString(result);
  let m = onclick.match(/t=([^&'"]+)/);
  if (!m) return '';
  let b64 = m[1].replace(/%3D/g,'=').replace(/\s/g,'');
  let bytes = java.util.Base64.getDecoder().decode(b64);
  return new java.lang.String(bytes, 'UTF-8');
}
